package com.school.management.entity; import jakarta.persistence.*;
@Entity public class ExamResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long studentId; private String subject; private String examName; private Double marks; private String grade; public ExamResult(){} public Long getId(){return id;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public String getExamName(){return examName;} public void setExamName(String v){examName=v;} public Double getMarks(){return marks;} public void setMarks(Double v){marks=v;} public String getGrade(){return grade;} public void setGrade(String v){grade=v;} }
